/* Writes the sprite into a 256-wide 16bpp tpage buffer, same encoding as
 * LoadTPageRGB (bpp 16: r<<11|g<<6|b, otherwise r<<10|g<<5|b). */
static void xb_patch_exit_to_dashboard(unsigned short *buf, int bpp16)
{
    if (buf == 0) return;
    for (int y = 0; y < XB_EXITDASH_H; y++) {
        for (int x = 0; x < XB_EXITDASH_W; x++) {
            const unsigned char *p = &xb_exitdash_rgb[(y * XB_EXITDASH_W + x) * 3];
            int r = p[0] >> 3, g = p[1] >> 3, b = p[2] >> 3;
            buf[(XB_EXITDASH_Y + y) * 256 + XB_EXITDASH_X + x] =
                (unsigned short)(bpp16 ? ((r << 11) | (g << 6) | b)
                                       : ((r << 10) | (g << 5) | b));
        }
    }
}
